139 :                         && equalStrings(testPrefix, getPrefix(node));
140 :             }
141 :             return false;
142 :         }
143 :         if (test instanceof NodeTypeTest) {
144 :             int nodeType = node.getNodeType();
145 :             switch (((NodeTypeTest) test).getNodeType()) {
146 :                 case Compiler.NODE_TYPE_NODE :
147 :                     return nodeType == Node.ELEMENT_NODE
148 :                             || nodeType == Node.DOCUMENT_NODE;
149 :                 case Compiler.NODE_TYPE_TEXT :
150 :                     return nodeType == Node.CDATA_SECTION_NODE
151 :                         || nodeType == Node.TEXT_NODE;
152 :                 case Compiler.NODE_TYPE_COMMENT :
153 :                     return nodeType == Node.COMMENT_NODE;
154 :                 case Compiler.NODE_TYPE_PI :
155 :                     return nodeType == Node.PROCESSING_INSTRUCTION_NODE;
156 :             }
157 :             return false;
158 :         }
