160 :             if (node.getNodeType() == Node.PROCESSING_INSTRUCTION_NODE) {
161 :                 String testPI = ((ProcessingInstructionTest) test).getTarget();
162 :                 String nodePI = ((ProcessingInstruction) node).getTarget();
163 :                 return testPI.equals(nodePI);
164 :             }
165 :         }
166 :         return false;
